import { path } from '@servicenow/sdk-build-core'
import { Project } from '../../src'
import { cleanTypeDefinitions } from '../../src/orchestrator/dependencies'
import { extractReferencesFromSourceFile } from '../../src/orchestrator/dependencies/script-definition-generator'

// Note: TypeGenerator is an internal class not exported from the module.
// We test it indirectly through ApplicationDependencies and directly test
// the exported cleanTypeDefinitions function.

describe('cleanTypeDefinitions', () => {
    it('should make function arguments optional', () => {
        const input = 'function foo(name: string, age: number): void {}'
        const result = cleanTypeDefinitions(input)

        expect(result.serverDTs).toContain('name?: string')
        expect(result.serverDTs).toContain('age?: number')
    })

    it('should preserve variable declarations', () => {
        const input = 'const myVar: string = "hello"'
        const result = cleanTypeDefinitions(input)

        expect(result.serverDTs).toContain('const myVar: string')
        expect(result.serverDTs).not.toContain('const myVar?: string')
    })

    it('should quote properties with dots', () => {
        const input = 'interface Test { user.name: string }'
        const result = cleanTypeDefinitions(input)

        expect(result.serverDTs).toContain("'user.name'?:")
    })

    it('should rename reserved word parameters', () => {
        const input = 'function foo(delete: boolean, function: string): void {}'
        const result = cleanTypeDefinitions(input)

        expect(result.serverDTs).toContain('delete_?:')
        expect(result.serverDTs).toContain('function_?:')
    })

    it('should remove static from constructors', () => {
        const input = 'class Test { static constructor() {} }'
        const result = cleanTypeDefinitions(input)

        expect(result.serverDTs).toContain('constructor()')
        expect(result.serverDTs).not.toContain('static constructor')
    })

    it('should add Java type aliases', () => {
        const input = 'interface Test {}'
        const result = cleanTypeDefinitions(input)

        expect(result.serverDTs).toContain('type ArrayList<T extends unknown = unknown> = T[]')
        expect(result.serverDTs).toContain('type StringList = string[]')
        expect(result.serverDTs).toContain('type List<T extends unknown = unknown> = T[]')
        expect(result.serverDTs).toContain('type TimeZone = string')
    })
})

describe('extractReferencesFromSourceFile', () => {
    const tests = [
        { expected: ['global.Foo'], code: 'global.Foo()', name: 'prefixed call expression' },
        { expected: ['global.Foo'], code: 'new global.Foo()', name: 'prefixed new expression' },
        { expected: ['global.Foo'], code: 'Foo()', name: 'local-scoped call expression' },
        { expected: ['global.Foo'], code: 'new Foo()', name: 'local-scoped new expression' },
        { expected: [], code: 'new Bar()', name: `nothing, because Bar is not a script include` },
        {
            expected: [],
            code: 'new Util()',
            name: `nothing, because Util is a script include from another scope so it requires a prefix`,
        },
        {
            expected: [],
            code: 'new sn_bad_scope.Util()',
            name: `nothing, because Util does not exist in sn_bad_scope`,
        },
        {
            expected: ['sn_app.Util'],
            code: 'new sn_app.Util()',
            name: `prefixed new expression from another scope, so long as it's prefixed`,
        },
        {
            expected: ['sn_app.Util'],
            code: 'sn_app.Util()',
            name: `prefixed call expression from another scope, so long as it's prefixed`,
        },
        { expected: [], code: 'var Foo = true', name: `nothing, because it's a locally defined variable` },
        {
            expected: ['global.Foo'],
            code: 'global.Foo.doSomething()',
            name: 'prefixed call expression on a static method',
        },
        {
            expected: ['global.Foo'],
            code: 'global.Foo.doSomething()',
            name: 'local-scoped call expression on a static method',
        },
        {
            expected: ['global.Foo'],
            code: 'var value = global.Foo.CONSTANT_VALUE',
            name: 'prefixed property access',
        },
        {
            expected: ['global.Foo'],
            code: 'var value = Foo.CONSTANT_VALUE',
            name: 'local-scoped property access',
        },
        {
            expected: [],
            code: 'Other.Foo.bar',
            name: 'nothing, because Other is not a known global',
        },
        {
            expected: [],
            code: 'new Other.Foo()',
            name: 'nothing, because Other is not a known global',
        },
        {
            expected: [],
            code: 'Other.Foo()',
            name: 'nothing, because Other is not a known global',
        },
    ]

    const project = new Project()
    const { scope } = project.getConfig()
    const filePath = path.join('src', 'fluent', 'script.js')

    for (const test of tests) {
        it(`should extract references from ${test.name}`, () => {
            const sourceFile = project.getCompiler().createSourceFile(filePath, test.code, { overwrite: true })
            const references = extractReferencesFromSourceFile(
                sourceFile,
                {
                    'global.Foo': '7a6ac65826119925b042989df10e44f5',
                    'sn_app.Util': 'b6ea9004778265e288e1e047f93230c1',
                },
                scope
            )

            expect(references).toEqual(test.expected)
        })
    }
})
